-- MakerWorld batch 2 (sea/satwa/religi/nama) - integrated products
-- Run in Supabase SQL Editor. Replaces/updates rows by slug.
ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, story = EXCLUDED.story, image_url = EXCLUDED.image_url, gallery = EXCLUDED.gallery, is_active = true, weight_g = EXCLUDED.weight_g, print_time_min = EXCLUDED.print_time_min, variants = EXCLUDED.variants, artists = EXCLUDED.artists;
